import 'package:honeywell_scanner/honeywell_scanner.dart';

void main() async {
  final scanner = HoneywellScanner(
    onScannerDecodeCallback: (data) => print('Scanned: ${data?.code}'),
    onScannerErrorCallback: (e) => print('Error: $e'),
  );
  if (await scanner.isSupported()) {
    await scanner.startScanner();
  }
}
